    QListWidget* list=new QListWidget;QSpinBox* id=new QSpinBox;QComboBox* speaker=new QComboBox;QPlainTextEdit* text=new QPlainTextEdit;QPlainTextEdit* alternate=new QPlainTextEdit;
    QLineEdit *iq=new QLineEdit,*conditions=new QLineEdit,*target=new QLineEdit,*effects=new QLineEdit;
    QLabel* alternateLabel=new QLabel;QLabel* feedback=new QLabel;
    Dialogue rows;int selected=-1;bool updating=false;std::function<void()> changed;
    explicit DialogueEditor(QWidget* parent=nullptr):QWidget(parent){auto layout=new QVBoxLayout(this);auto help=new QLabel("NPC lines are followed by their player responses in ID order. Target: 0 ends the dialogue; a positive ID goes to an NPC line; a negative number resumes the companion SCR instruction.");help->setWordWrap(true);layout->addWidget(help);auto split=new QSplitter;layout->addWidget(split,1);auto left=new QWidget;auto l=new QVBoxLayout(left);l->addWidget(list);auto actions=new QHBoxLayout;auto npc=new QPushButton("Add NPC line"),reply=new QPushButton("Add response"),remove=new QPushButton("Delete");actions->addWidget(npc);actions->addWidget(reply);actions->addWidget(remove);l->addLayout(actions);split->addWidget(left);
        auto right=new QWidget;auto f=new QFormLayout(right);id->setRange(1,9999999);speaker->addItems({"NPC","Player response"});f->addRow("Line ID",id);f->addRow("Speaker",speaker);text->setMaximumHeight(160);alternate->setMaximumHeight(100);f->addRow("Text",text);f->addRow(alternateLabel,alternate);f->addRow("Intelligence",iq);f->addRow("Conditions (native)",conditions);f->addRow("Target",target);f->addRow("Effects (native)",effects);auto jump=new QPushButton("Go to target"),preview=new QPushButton("Preview conversation");f->addRow(jump,preview);split->addWidget(right);split->setSizes({390,610});feedback->setWordWrap(true);layout->addWidget(feedback);
        auto edited=[this]{if(updating)return;store();if(changed)changed();};for(auto e:{iq,conditions,target,effects})connect(e,&QLineEdit::textEdited,this,edited);connect(id,&QSpinBox::valueChanged,this,edited);connect(text,&QPlainTextEdit::textChanged,this,edited);connect(alternate,&QPlainTextEdit::textChanged,this,edited);
        connect(speaker,&QComboBox::currentIndexChanged,this,[this,edited](int index){if(updating)return;iq->setText(index==0?"":"1");alternate->clear();edited();labels();});
        connect(list,&QListWidget::currentRowChanged,this,[this](int index){store();selected=index;showLine();});connect(npc,&QPushButton::clicked,this,[this]{add(false);});connect(reply,&QPushButton::clicked,this,[this]{add(true);});connect(remove,&QPushButton::clicked,this,[this]{if(selected<0)return;rows.erase(rows.begin()+selected);selected=-1;refresh();if(changed)changed();});
        connect(jump,&QPushButton::clicked,this,[this]{bool ok;int value=target->text().toInt(&ok);if(ok && value>0)for(int i=0;i<int(rows.size());i++)if(rows[i].fields[0].toInt()==value){list->setCurrentRow(i);return;}feedback->setText("This target does not refer to an NPC line in this dialogue.");});connect(preview,&QPushButton::clicked,this,[this]{try{previewConversation();}catch(const std::exception& e){feedback->setText(e.what());}});
    }
    void labels(){bool npc=speaker->currentIndex()==0;alternateLabel->setText(npc?"Text for a female player":"Gender filter (blank / 0 / 1)");iq->setEnabled(!npc);iq->setToolTip("Blank for NPC; positive = minimum intelligence; negative = maximum intelligence.");}
    void load(Dialogue lines){rows=std::move(lines);selected=-1;refresh();}
    Dialogue value(){store();auto sorted=rows;std::stable_sort(sorted.begin(),sorted.end(),[](auto& a,auto& b){return dialogue_integer(a.fields[0])<dialogue_integer(b.fields[0]);});return sorted;}
    void store(){if(updating || selected<0 || selected>=int(rows.size()))return;auto& f=rows[selected].fields;f={QString::number(id->value()),text->toPlainText(),alternate->toPlainText(),iq->text(),conditions->text(),target->text(),effects->text()};if(auto item=list->item(selected))item->setText(summary(rows[selected]));}
    static QString summary(const DialogueLine& row){return row.fields[0]+(row.fields[3].trimmed().isEmpty()?" · NPC · ":" · Player · ")+row.fields[1].simplified().left(100);}
    void showLine(){updating=true;bool valid=selected>=0 && selected<int(rows.size());for(QWidget* widget:std::initializer_list<QWidget*>{id,speaker,text,alternate,iq,conditions,target,effects})widget->setEnabled(valid);if(valid){auto& f=rows[selected].fields;id->setValue(f[0].toInt());speaker->setCurrentIndex(f[3].trimmed().isEmpty()?0:1);text->setPlainText(f[1]);alternate->setPlainText(f[2]);iq->setText(f[3]);conditions->setText(f[4]);target->setText(f[5]);effects->setText(f[6]);labels();}updating=false;}
